package com.sih.analytics.service; import static org.junit.jupiter.api.Assertions.*; import com.sih.analytics.dto.AnalyticsDtos.*; import com.sih.shared.tenant.*; import java.math.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.*; @SpringBootTest class AnalyticsServiceIT{@Autowired AnalyticsService s;@AfterEach void c(){TenantContext.clear();}@Test void keepsLatestMetricPerKey(){TenantContext.setCurrentTenant("a");s.record(new MetricRequest("CLINICAL","READMISSION","Réadmissions",new BigDecimal("4"),"%",null,"dpi"));s.record(new MetricRequest("CLINICAL","READMISSION","Réadmissions",new BigDecimal("3"),"%",null,"dpi"));assertEquals(1,s.dashboard().clinical().size());assertEquals(0,new BigDecimal("3").compareTo(s.dashboard().clinical().get(0).value()));}@Test void isolatesMetrics(){TenantContext.setCurrentTenant("a");s.record(new MetricRequest("FINANCIAL","DSO","DSO",new BigDecimal("12"),"jours",null,"rcm"));TenantContext.setCurrentTenant("b");assertTrue(s.dashboard().financial().isEmpty());}}